### 5.4 Helper for Language-Aware Field Access

```typescript
// src/lib/utils.ts
import { Locale } from '@/lib/i18n';

export function localized<T>(
  obj: T,
  field: string,
  lang: Locale
): string {
  const key = lang === 'zh' ? `${field}Zh` : `${field}En`;
  return (obj as Record<string, string>)[key] ?? '';
}
```

Usage: `localized(trek, 'name', lang)` returns `trek.nameEn` or `trek.nameZh`.

