import { useEffect } from "react";

export default function HtmlLangSetter({ lang }: { lang: string }) {
  useEffect(() => {
    document.documentElement.lang = lang;
  }, [lang]);
  return null;
}

"use client";

import { usePathname } from "next/navigation";
import Link from "next/link";

export default function LanguageSwitcher({
  currentLang,
}: {
  currentLang: string;
}) {
  const pathname = usePathname();
  const targetLang = currentLang === "en" ? "zh" : "en";
  const targetPath = pathname.replace(`/${currentLang}`, `/${targetLang}`);

  return (
    <Link
      href={targetPath}
      className="rounded-full border border-white/30 px-3 py-1 text-sm font-medium text-white transition-colors hover:bg-white/10"
    >
      {targetLang === "zh" ? "中文" : "English"}
    </Link>
  );
}

