"use client";

import { useState } from "react";
import Image from "next/image";

interface GalleryImage {
  src: string;
  alt: string;
}

export default function GalleryGrid({ images }: { images: GalleryImage[] }) {
  const [selected, setSelected] = useState<number | null>(null);

  return (
    <>
      {/* Masonry-style grid */}
      <div className="columns-1 gap-4 sm:columns-2 lg:columns-3">
        {images.map((img, i) => {
          // Vary heights for visual interest
          const heights = ["h-64", "h-80", "h-72", "h-96", "h-64", "h-80"];
          const h = heights[i % heights.length];
          return (
            <button
              key={i}
              className={`group relative mb-4 w-full overflow-hidden rounded-xl ${h} bg-gray-200`}
              onClick={() => setSelected(i)}
            >
              {/* Placeholder gradient when images aren't available */}
              <div
                className={`absolute inset-0 bg-gradient-to-br ${
                  [
                    "from-emerald-800 to-emerald-600",
                    "from-sky-800 to-sky-600",
                    "from-amber-800 to-amber-600",
                    "from-violet-800 to-violet-600",
                    "from-rose-800 to-rose-600",
                    "from-teal-800 to-teal-600",
                    "from-indigo-800 to-indigo-600",
                    "from-orange-800 to-orange-600",
                    "from-cyan-800 to-cyan-600",
                    "from-green-800 to-green-600",
                    "from-red-800 to-red-600",
                    "from-blue-800 to-blue-600",
                  ][i % 12]
                }`}
              />
              {/* Mountain decoration */}
              <svg
                className="absolute bottom-0 left-0 right-0 h-1/3 text-white/10"
                viewBox="0 0 400 100"
                fill="currentColor"
                preserveAspectRatio="none"
              >
                <path d="M0,100 L0,60 Q50,20 100,50 Q150,80 200,30 Q250,0 300,40 Q350,70 400,20 L400,100 Z" />
              </svg>
              <div className="absolute inset-0 flex items-center justify-center">
                <span className="text-sm font-medium text-white/60">
                  {img.alt}
                </span>
              </div>
              <div className="absolute inset-0 bg-black/0 transition-colors group-hover:bg-black/20" />
            </button>
          );
        })}
      </div>

      {/* Lightbox */}
      {selected !== null && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 p-4"
          onClick={() => setSelected(null)}
        >
          <button
            className="absolute right-4 top-4 text-white/70 transition-colors hover:text-white"
            onClick={() => setSelected(null)}
          >
            <svg className="h-8 w-8" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18 18 6M6 6l12 12" />
            </svg>
          </button>

          {/* Nav buttons */}
          <button
            className="absolute left-4 text-white/70 transition-colors hover:text-white"
            onClick={(e) => {
              e.stopPropagation();
              setSelected(selected > 0 ? selected - 1 : images.length - 1);
            }}
          >
            <svg className="h-10 w-10" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5 8.25 12l7.5-7.5" />
            </svg>
          </button>

          <div className="max-h-[80vh] max-w-4xl text-center">
            <div className="relative mx-auto flex h-[60vh] w-[80vw] max-w-4xl items-center justify-center">
              <div
                className={`h-full w-full rounded-lg bg-gradient-to-br ${
                  [
                    "from-emerald-800 to-emerald-600",
                    "from-sky-800 to-sky-600",
                    "from-amber-800 to-amber-600",
                    "from-violet-800 to-violet-600",
                    "from-rose-800 to-rose-600",
                    "from-teal-800 to-teal-600",
                    "from-indigo-800 to-indigo-600",
                    "from-orange-800 to-orange-600",
                    "from-cyan-800 to-cyan-600",
                    "from-green-800 to-green-600",
