import type { Locale } from "./i18n";

export function localized<T extends Record<string, unknown>>(
  obj: T,
  field: string,
  lang: Locale,
): string {
  const key = lang === "zh" ? `${field}Zh` : `${field}En`;
  return (obj[key] as string) ?? "";
}

