import Link from "next/link";
import type { Dictionary } from "@/app/[lang]/dictionaries";

export default function HeroBanner({
  lang,
  dict,
}: {
  lang: string;
  dict: Dictionary["home"]["hero"];
}) {
  return (
    <section className="relative flex min-h-[85vh] items-center justify-center overflow-hidden bg-primary-dark">
      {/* Background image with overlay */}
      <div
        className="absolute inset-0 bg-cover bg-center bg-no-repeat"
        style={{ backgroundImage: "url(/images/banner.jpg)" }}
      />
      <div className="absolute inset-0 bg-gradient-to-b from-primary-dark/70 via-primary-dark/50 to-primary-dark/80" />

      <div className="relative z-10 mx-auto max-w-4xl px-4 text-center sm:px-6">
        <h1 className="mb-6 text-4xl font-bold leading-tight text-white sm:text-5xl md:text-6xl">
          {dict.title}
        </h1>
        <p className="mx-auto mb-10 max-w-2xl text-lg text-white/80 sm:text-xl">
          {dict.subtitle}
        </p>
        <div className="flex flex-col items-center gap-4 sm:flex-row sm:justify-center">
          <Link
            href={`/${lang}/treks`}
            className="rounded-full bg-accent px-8 py-3 text-lg font-semibold text-white transition-colors hover:bg-accent-light"
          >
            {dict.cta}
          </Link>
          <Link
            href={`/${lang}/about`}
            className="rounded-full border-2 border-white/40 px-8 py-3 text-lg font-semibold text-white transition-colors hover:bg-white/10"
          >
            {dict.secondary}
          </Link>
        </div>
      </div>

      {/* Scroll indicator */}
      <div className="absolute bottom-8 left-1/2 -translate-x-1/2 animate-bounce">
        <svg
          className="h-6 w-6 text-white/60"
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M19 14l-7 7m0 0l-7-7m7 7V3"
          />
        </svg>
      </div>
    </section>
  );
}

import type { Dictionary } from "@/app/[lang]/dictionaries";

const activityIcons: Record<string, string> = {
  hiking: "M13 7h-2v4H7v2h4v4h2v-4h4v-2h-4V7zm-1-5C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2z",
  yoga: "M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z",
  temples: "M12 3L1 9l4 2.18v6L12 21l7-3.82v-6l2-1.09V17h2V9L12 3z",
  paragliding: "M21 16v-2l-8-5V3.5c0-.83-.67-1.5-1.5-1.5S10 2.67 10 3.5V9l-8 5v2l8-2.5V19l-2 1.5V22l3.5-1 3.5 1v-1.5L13 19v-5.5l8 2.5z",
  rafting: "M20 21c-1.39 0-2.78-.47-4-1.32-2.44 1.71-5.56 1.71-8 0C6.78 20.53 5.39 21 4 21H2v2h2c1.38 0 2.74-.35 4-.99 2.52 1.29 5.48 1.29 8 0 1.26.65 2.62.99 4 .99h2v-2h-2z",
  skiing: "M18 13c-.55 0-1 .45-1 1v3c0 .55.45 1 1 1s1-.45 1-1v-3c0-.55-.45-1-1-1z",
  cityTours: "M15 11V5l-3-3-3 3v2H3v14h18V11h-6zm-8 8H5v-2h2v2zm0-4H5v-2h2v2zm0-4H5V9h2v2zm6 8h-2v-2h2v2zm0-4h-2v-2h2v2zm0-4h-2V9h2v2zm0-4h-2V5h2v2zm6 12h-2v-2h2v2zm0-4h-2v-2h2v2z",
};

const activityColors = [
  "from-emerald-500 to-emerald-700",
  "from-purple-500 to-purple-700",
  "from-amber-500 to-amber-700",
  "from-sky-500 to-sky-700",
  "from-blue-500 to-blue-700",
  "from-cyan-500 to-cyan-700",
  "from-rose-500 to-rose-700",
];

const activityKeys = [
  "hiking",
  "yoga",
  "temples",
  "paragliding",
  "rafting",
  "skiing",
  "cityTours",
] as const;

export default function ActivityCategories({
  dict,
}: {
  dict: Dictionary["home"]["activities"];
}) {
  return (
    <section className="bg-white py-20">
      <div className="mx-auto max-w-7xl px-4 sm:px-6">
        <div className="mb-12 text-center">
          <h2 className="mb-4 text-3xl font-bold text-primary-dark sm:text-4xl">
            {dict.title}
          </h2>
          <p className="mx-auto max-w-2xl text-muted">{dict.subtitle}</p>
        </div>

        <div className="grid gap-6 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4">
          {activityKeys.map((key, i) => {
            const activity = dict[key];
            return (
              <div
                key={key}
                className="group overflow-hidden rounded-2xl bg-white shadow-md transition-all hover:-translate-y-1 hover:shadow-xl"
              >
                <div
                  className={`flex h-32 items-center justify-center bg-gradient-to-br ${activityColors[i]}`}
                >
                  <svg
                    className="h-12 w-12 text-white transition-transform group-hover:scale-110"
                    fill="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path d={activityIcons[key]} />
                  </svg>
                </div>
                <div className="p-5">
                  <h3 className="mb-2 text-lg font-semibold text-primary-dark">
                    {activity.name}
                  </h3>
                  <p className="text-sm text-muted">{activity.description}</p>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

