import Image from "next/image";
import type { Dictionary } from "@/app/[lang]/dictionaries";

const activityKeys = [
  "hiking",
  "yoga",
  "temples",
  "paragliding",
  "rafting",
  "skiing",
  "cityTours",
] as const;

const activityImages: Record<string, string> = {
  hiking: "/images/activities/hiking.jpg",
  yoga: "/images/activities/yoga.jpg",
  temples: "/images/activities/temples.jpg",
  paragliding: "/images/activities/paragliding.jpg",
  rafting: "/images/activities/rafting.jpg",
  skiing: "/images/activities/skiing.jpg",
  cityTours: "/images/activities/city.jpg",
};

export default function ActivityCategories({
  dict,
}: {
  dict: Dictionary["home"]["activities"];
}) {
  return (
    <section className="bg-white py-24">
      <div className="mx-auto max-w-7xl px-4 sm:px-6">
        <div className="mb-16 text-center">
          <span className="mb-3 inline-block text-sm font-semibold uppercase tracking-widest text-accent">
            {dict.title}
          </span>
          <p className="mx-auto max-w-2xl text-lg text-muted">
            {dict.subtitle}
          </p>
        </div>

        {/* Bento-style grid */}
        <div className="grid auto-rows-[200px] gap-4 md:grid-cols-3 lg:grid-cols-4">
          {activityKeys.map((key, i) => {
            const activity = dict[key];
            // Make hiking and temples span 2 rows for visual variety
            const tall = i === 0 || i === 2;
            return (
              <div
                key={key}
                className={`group relative overflow-hidden rounded-2xl ${
                  tall ? "row-span-2" : ""
                } ${i === 0 ? "md:col-span-2 lg:col-span-1" : ""}`}
              >
                <Image
                  src={activityImages[key]}
                  alt={activity.name}
                  fill
                  className="object-cover transition-transform duration-700 group-hover:scale-110"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent transition-all group-hover:from-black/90" />

                <div className="absolute bottom-0 left-0 right-0 p-5">
                  <h3 className="mb-1 text-lg font-bold text-white">
                    {activity.name}
                  </h3>
                  <p className="text-sm leading-snug text-white/70 opacity-0 transition-opacity duration-300 group-hover:opacity-100">
                    {activity.description}
                  </p>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

