import Link from "next/link";
import Image from "next/image";
import type { Dictionary } from "@/app/[lang]/dictionaries";
import { treks } from "@/data/treks";
import { localized } from "@/lib/utils";
import type { Locale } from "@/lib/i18n";

export default function FeaturedTreks({
  lang,
  dict,
  treksDict,
}: {
  lang: string;
  dict: Dictionary["home"]["featuredTreks"];
  treksDict: Dictionary["treks"];
}) {
  const featured = treks.filter((t) => t.featured);

  return (
    <section className="bg-muted-light py-20">
      <div className="mx-auto max-w-7xl px-4 sm:px-6">
        <div className="mb-12 text-center">
          <h2 className="mb-4 text-3xl font-bold text-primary-dark sm:text-4xl">
            {dict.title}
          </h2>
          <p className="mx-auto max-w-2xl text-muted">{dict.subtitle}</p>
        </div>

        <div className="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
          {featured.map((trek) => (
            <Link
              key={trek.slug}
              href={`/${lang}/treks/${trek.slug}`}
              className="group overflow-hidden rounded-2xl bg-white shadow-md transition-all hover:-translate-y-1 hover:shadow-xl"
            >
              <div className="relative h-56 overflow-hidden">
                <Image
                  src={trek.heroImage}
                  alt={localized(trek, "name", lang as Locale)}
                  fill
                  className="object-cover transition-transform duration-500 group-hover:scale-110"
                />
                <div className="absolute right-3 top-3">
                  <span
                    className={`rounded-full px-3 py-1 text-xs font-semibold text-white ${
                      trek.difficulty === "easy"
                        ? "bg-green-500"
                        : trek.difficulty === "moderate"
                          ? "bg-yellow-500"
                          : trek.difficulty === "challenging"
                            ? "bg-orange-500"
                            : "bg-red-500"
                    }`}
                  >
                    {treksDict.difficultyLevels[trek.difficulty]}
                  </span>
                </div>
              </div>
              <div className="p-6">
                <h3 className="mb-2 text-xl font-bold text-primary-dark">
                  {localized(trek, "name", lang as Locale)}
                </h3>
                <p className="mb-4 line-clamp-2 text-sm text-muted">
                  {localized(trek, "description", lang as Locale)}
                </p>
                <div className="flex items-center justify-between text-sm">
                  <span className="text-muted">
                    {trek.durationDays} {treksDict.days}
                  </span>
                  <span className="font-bold text-accent">
                    {treksDict.price} ${trek.priceUSD}
                  </span>
                </div>
              </div>
            </Link>
          ))}
        </div>

        <div className="mt-10 text-center">
          <Link
            href={`/${lang}/treks`}
            className="inline-block rounded-full border-2 border-primary bg-transparent px-8 py-3 font-semibold text-primary transition-colors hover:bg-primary hover:text-white"
          >
            {dict.viewAll}
          </Link>
        </div>
      </div>
    </section>
  );
}

