"use client";

import { useState } from "react";
import type { TrekItineraryDay } from "@/types/trek";
import type { Locale } from "@/lib/i18n";
import { localized } from "@/lib/utils";

export default function ItineraryAccordion({
  itinerary,
  lang,
  dayLabel,
}: {
  itinerary: TrekItineraryDay[];
  lang: Locale;
  dayLabel: string;
}) {
  const [openDay, setOpenDay] = useState<number | null>(0);

  return (
    <div className="space-y-3">
      {itinerary.map((day, i) => {
        const isOpen = openDay === i;
        return (
          <div
            key={day.day}
            className="overflow-hidden rounded-xl border border-gray-100 bg-white transition-shadow hover:shadow-md"
          >
            <button
              className="flex w-full items-center gap-4 px-6 py-4 text-left"
              onClick={() => setOpenDay(isOpen ? null : i)}
            >
              <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-primary text-sm font-bold text-white">
                {lang === "zh" ? `${dayLabel}${day.day}天` : `${day.day}`}
              </span>
              <span className="flex-1 font-semibold text-primary-dark">
                {localized(day, "title", lang)}
              </span>
              {day.altitude && (
                <span className="hidden text-sm text-muted sm:block">
                  {day.altitude.toLocaleString()}m
                </span>
              )}
              <svg
                className={`h-5 w-5 shrink-0 text-muted transition-transform ${isOpen ? "rotate-180" : ""}`}
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
                strokeWidth={2}
              >
                <path strokeLinecap="round" strokeLinejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5" />
              </svg>
            </button>
            {isOpen && (
              <div className="border-t border-gray-100 px-6 py-4">
                <p className="text-foreground/70">
                  {localized(day, "description", lang)}
                </p>
                {(day.altitude || day.walkingHours) && (
                  <div className="mt-3 flex gap-4 text-sm text-muted">
                    {day.altitude && (
                      <span className="flex items-center gap-1">
                        <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
                          <path strokeLinecap="round" strokeLinejoin="round" d="M3 7.5 7.5 3m0 0L12 7.5M7.5 3v13.5m13.5-6L16.5 15m0 0L12 10.5m4.5 4.5V1.5" />
                        </svg>
                        {day.altitude.toLocaleString()}m
                      </span>
                    )}
                    {day.walkingHours && (
                      <span className="flex items-center gap-1">
                        <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
                          <path strokeLinecap="round" strokeLinejoin="round" d="M12 6v6h4.5m4.5 0a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z" />
                        </svg>
                        {day.walkingHours}h
                      </span>
                    )}
                  </div>
                )}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

