"use client";

import { useState, useCallback, lazy, Suspense } from "react";
import type { TrekItineraryDay } from "@/types/trek";
import type { TrekWaypoint } from "@/data/trekCoordinates";
import type { Locale } from "@/lib/i18n";
import ItineraryAccordion from "./ItineraryAccordion";

// Lazy-load Leaflet map (avoids SSR issues with window)
const TrekMap = lazy(() => import("./TrekMap"));

export default function ItineraryWithMap({
  itinerary,
  waypoints,
  lang,
  dayLabel,
  itineraryTitle,
}: {
  itinerary: TrekItineraryDay[];
  waypoints: TrekWaypoint[];
  lang: Locale;
  dayLabel: string;
  itineraryTitle: string;
}) {
  const [activeDay, setActiveDay] = useState<number | null>(
    itinerary[0]?.day ?? null,
  );

  const handleDayChange = useCallback((day: number) => {
    setActiveDay(day);
  }, []);

  return (
    <div className="grid gap-8 lg:grid-cols-5">
      {/* Itinerary - left side */}
      <div className="lg:col-span-3">
        <h2 className="mb-6 text-2xl font-bold text-primary-dark">
          {itineraryTitle}
        </h2>
        <ItineraryAccordion
          itinerary={itinerary}
          lang={lang}
          dayLabel={dayLabel}
          onDayChange={handleDayChange}
        />
      </div>

      {/* Map - sticky right side */}
      <div className="lg:col-span-2">
        <div className="sticky top-24 h-[500px] lg:h-[600px]">
          <Suspense
            fallback={
              <div className="flex h-full items-center justify-center rounded-2xl bg-muted-light">
                <div className="text-center text-muted">
                  <svg
                    className="mx-auto mb-2 h-8 w-8 animate-spin"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                    strokeWidth={1.5}
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0 3.181 3.183a8.25 8.25 0 0 0 13.803-3.7M4.031 9.865a8.25 8.25 0 0 1 13.803-3.7l3.181 3.182m0-4.991v4.99"
                    />
                  </svg>
                  <span className="text-sm">
                    {lang === "zh" ? "載入地圖中..." : "Loading map..."}
                  </span>
                </div>
              </div>
            }
          >
            <TrekMap waypoints={waypoints} activeDay={activeDay} lang={lang} />
          </Suspense>

          {/* Altitude indicator */}
          {activeDay !== null && (
            <div className="mt-3 rounded-xl bg-white p-3 text-center shadow-sm ring-1 ring-gray-100">
              {(() => {
                const wp = waypoints.find((w) => w.day === activeDay);
                if (!wp) return null;
                return (
                  <div className="flex items-center justify-center gap-4 text-sm">
                    <span className="font-semibold text-primary-dark">
                      {lang === "zh" ? `第${wp.day}天` : `Day ${wp.day}`}
                    </span>
                    <span className="text-muted">
                      {lang === "zh" ? wp.labelZh : wp.labelEn}
                    </span>
                    <span className="font-mono text-accent">
                      {wp.altitude.toLocaleString()}m
                    </span>
                  </div>
                );
              })()}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

