                    <span className="text-muted">{dict.treks.difficulty}</span>
                    <span className={`rounded-full px-3 py-0.5 text-xs font-bold ${difficultyColor}`}>
                      {dict.treks.difficultyLevels[trek.difficulty]}
                    </span>
                  </div>
                  <div className="flex justify-between border-b border-gray-100 pb-3">
                    <span className="text-muted">{dict.treks.maxAltitude}</span>
                    <span className="font-semibold">
                      {trek.maxAltitude.toLocaleString()}m
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-muted">{dict.treks.bestSeason}</span>
                    <span className="text-right font-semibold">
                      {(l === "zh" ? trek.bestSeasonsZh : trek.bestSeasons).join(
                        ", ",
                      )}
                    </span>
                  </div>
                </div>

                <Link
                  href={`/${lang}/contact`}
                  className="block w-full rounded-full bg-accent py-3 text-center font-semibold text-white transition-colors hover:bg-accent-light"
                >
                  {dict.treks.bookNow}
                </Link>
                <Link
                  href={`/${lang}/contact`}
                  className="mt-3 block w-full rounded-full border-2 border-primary py-3 text-center font-semibold text-primary transition-colors hover:bg-primary hover:text-white"
                >
                  {dict.treks.inquire}
                </Link>
              </div>
            </div>
          </div>
        </div>
      </section>
    </>
  );
}

