"use client";

import { useEffect, useRef } from "react";
import type { TrekItineraryDay } from "@/types/trek";
import type { Locale } from "@/lib/i18n";
import { localized } from "@/lib/utils";

export default function ItineraryAccordion({
  itinerary,
  lang,
  dayLabel,
  onDayChange,
}: {
  itinerary: TrekItineraryDay[];
  lang: Locale;
  dayLabel: string;
  onDayChange?: (day: number) => void;
}) {
  const dayRefs = useRef<(HTMLDivElement | null)[]>([]);

  useEffect(() => {
    if (!onDayChange) return;

    const observer = new IntersectionObserver(
      (entries) => {
        // Find the most visible entry
        let best: IntersectionObserverEntry | null = null;
        for (const entry of entries) {
          if (
            entry.isIntersecting &&
            (!best || entry.intersectionRatio > best.intersectionRatio)
          ) {
            best = entry;
          }
        }
        if (best) {
          const idx = dayRefs.current.indexOf(best.target as HTMLDivElement);
          if (idx >= 0) {
            onDayChange(itinerary[idx].day);
          }
        }
      },
      { threshold: [0.3, 0.5, 0.7], rootMargin: "-20% 0px -40% 0px" },
    );

    for (const ref of dayRefs.current) {
      if (ref) observer.observe(ref);
    }

    return () => observer.disconnect();
  }, [onDayChange, itinerary]);

  return (
    <div className="space-y-6">
      {itinerary.map((day, i) => (
        <div
          key={day.day}
          ref={(el) => {
            dayRefs.current[i] = el;
          }}
          className="rounded-xl border border-gray-100 bg-white p-6 shadow-sm"
        >
          <div className="mb-3 flex items-center gap-4">
            <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-accent text-sm font-bold text-white">
              {lang === "zh" ? `${dayLabel}${day.day}天` : `${day.day}`}
            </span>
            <h3 className="flex-1 text-lg font-semibold text-primary-dark">
              {localized(day, "title", lang)}
            </h3>
          </div>

          <p className="mb-3 leading-relaxed text-foreground/70">
            {localized(day, "description", lang)}
          </p>

          {(day.altitude || day.walkingHours) && (
            <div className="flex gap-4 text-sm text-muted">
              {day.altitude && (
                <span className="flex items-center gap-1">
                  <svg
                    className="h-4 w-4"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                    strokeWidth={1.5}
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      d="M3 7.5 7.5 3m0 0L12 7.5M7.5 3v13.5m13.5-6L16.5 15m0 0L12 10.5m4.5 4.5V1.5"
                    />
                  </svg>
                  {day.altitude.toLocaleString()}m
                </span>
              )}
              {day.walkingHours && (
                <span className="flex items-center gap-1">
                  <svg
                    className="h-4 w-4"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                    strokeWidth={1.5}
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      d="M12 6v6h4.5m4.5 0a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z"
                    />
                  </svg>
                  {day.walkingHours}h
                </span>
              )}
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

