tool_use_result.originalFile:
"use client";

import type { TrekWaypoint } from "@/data/trekCoordinates";
import type { Locale } from "@/lib/i18n";

export default function AltitudeProfile({
  waypoints,
  activeDay,
  lang,
}: {
  waypoints: TrekWaypoint[];
  activeDay: number | null;
  lang: Locale;
}) {
  if (waypoints.length < 2) return null;

  const maxAlt = Math.max(...waypoints.map((w) => w.altitude));
  const minAlt = Math.min(...waypoints.map((w) => w.altitude));
  const altRange = maxAlt - minAlt || 1;

  const w = 400;
  const h = 80;
  const padTop = 8;
  const padBottom = 18;
  const chartH = h - padTop - padBottom;
  const step = w / (waypoints.length - 1);

  const activeIndex = activeDay
    ? waypoints.findIndex((wp) => wp.day === activeDay)
    : 0;

  // Build the area + line path
  const points = waypoints.map((wp, i) => ({
    x: i * step,
    y: padTop + chartH - ((wp.altitude - minAlt) / altRange) * chartH,
  }));

  const linePath = points.map((p, i) => `${i === 0 ? "M" : "L"}${p.x},${p.y}`).join(" ");
  const areaPath = `${linePath} L${points[points.length - 1].x},${h - padBottom} L${points[0].x},${h - padBottom} Z`;

  // Completed area (up to active index)
  const completedPoints = points.slice(0, activeIndex + 1);
  const completedLine = completedPoints.map((p, i) => `${i === 0 ? "M" : "L"}${p.x},${p.y}`).join(" ");
  const completedArea =
    completedPoints.length > 1
      ? `${completedLine} L${completedPoints[completedPoints.length - 1].x},${h - padBottom} L${completedPoints[0].x},${h - padBottom} Z`
      : "";

  const activeWp = activeIndex >= 0 ? waypoints[activeIndex] : null;
  const activePoint = activeIndex >= 0 ? points[activeIndex] : null;

  return (
    <div className="rounded-xl bg-white p-3 shadow-sm ring-1 ring-gray-100">
      <svg viewBox={`0 0 ${w} ${h}`} className="w-full" preserveAspectRatio="none">
        {/* Full profile area (faded) */}
        <path d={areaPath} fill="#1b4332" opacity={0.06} />
        <path d={linePath} fill="none" stroke="#1b4332" strokeWidth={1.5} opacity={0.2} />

        {/* Completed area (highlighted) */}
        {completedArea && (
          <>
            <path d={completedArea} fill="#e76f51" opacity={0.15} />
            <path d={completedLine} fill="none" stroke="#e76f51" strokeWidth={2} opacity={0.8} />
          </>
        )}

        {/* Day dots */}
        {points.map((p, i) => {
          const isActive = i === activeIndex;
          const isCompleted = activeIndex >= 0 && i <= activeIndex;
          return (
            <circle
              key={i}
              cx={p.x}
              cy={p.y}
              r={isActive ? 4 : 2.5}
              fill={isCompleted ? "#e76f51" : "#1b4332"}
              opacity={isActive ? 1 : isCompleted ? 0.7 : 0.25}
            />
          );
        })}

        {/* Active day vertical line */}
        {activePoint && (
          <line
            x1={activePoint.x}
            y1={padTop}
            x2={activePoint.x}
            y2={h - padBottom}
            stroke="#e76f51"
            strokeWidth={1}
            strokeDasharray="3 3"
            opacity={0.5}
          />
        )}

        {/* Min/max altitude labels */}
        <text x={w - 2} y={padTop + 8} textAnchor="end" fontSize={8} fill="#888" opacity={0.6}>
          {maxAlt.toLocaleString()}m
        </text>
        <text x={w - 2} y={h - padBottom - 2} textAnchor="end" fontSize={8} fill="#888" opacity={0.6}>
          {minAlt.toLocaleString()}m
        </text>
      </svg>

      {/* Active day info */}
      {activeWp && (
        <div className="mt-1 flex items-center justify-center gap-3 text-xs">
          <span className="font-semibold text-primary-dark">
            {lang === "zh" ? `第${activeWp.day}天` : `Day ${activeWp.day}`}
          </span>
          <span className="text-muted">
            {lang === "zh" ? activeWp.labelZh : activeWp.labelEn}
          </span>
          <span className="font-mono text-accent">
            {activeWp.altitude.toLocaleString()}m
          </span>
        </div>
      )}
    </div>
  );
}

