"use client";

import { useEffect, useRef, useMemo } from "react";
import {
  MapContainer,
  TileLayer,
  Polyline,
  CircleMarker,
  Tooltip,
  useMap,
} from "react-leaflet";
import type { LatLngBoundsExpression } from "leaflet";
import "leaflet/dist/leaflet.css";
import type { TrekWaypoint } from "@/data/trekCoordinates";
import type { Locale } from "@/lib/i18n";

function MapController({
  waypoints,
  activeDay,
}: {
  waypoints: TrekWaypoint[];
  activeDay: number | null;
}) {
  const map = useMap();
  const boundsRef = useRef<LatLngBoundsExpression | null>(null);

  // Compute and fit full route bounds once
  useEffect(() => {
    if (waypoints.length === 0) return;
    const lats = waypoints.map((w) => w.lat);
    const lngs = waypoints.map((w) => w.lng);
    const bounds: LatLngBoundsExpression = [
      [Math.min(...lats) - 0.05, Math.min(...lngs) - 0.05],
      [Math.max(...lats) + 0.05, Math.max(...lngs) + 0.05],
    ];
    boundsRef.current = bounds;
    map.fitBounds(bounds, { padding: [40, 40] });
  }, [map, waypoints]);

  // Gentle re-center if active waypoint is near the edge, but keep zoom level
  useEffect(() => {
    if (activeDay === null || !boundsRef.current) return;
    const wp = waypoints.find((w) => w.day === activeDay);
    if (!wp) return;

    const mapBounds = map.getBounds();
    const point = { lat: wp.lat, lng: wp.lng };

    // Check if the point is within the inner 60% of the viewport
    const latRange = mapBounds.getNorth() - mapBounds.getSouth();
    const lngRange = mapBounds.getEast() - mapBounds.getWest();
    const margin = 0.2;

    const inInner =
      point.lat > mapBounds.getSouth() + latRange * margin &&
      point.lat < mapBounds.getNorth() - latRange * margin &&
      point.lng > mapBounds.getWest() + lngRange * margin &&
      point.lng < mapBounds.getEast() - lngRange * margin;

    if (!inInner) {
      map.panTo([wp.lat, wp.lng], { animate: true, duration: 0.6 });
    }
  }, [map, activeDay, waypoints]);

  return null;
}

export default function TrekMap({
  waypoints,
  activeDay,
  lang,
}: {
  waypoints: TrekWaypoint[];
  activeDay: number | null;
  lang: Locale;
}) {
  const routePositions = useMemo(
    () => waypoints.map((w) => [w.lat, w.lng] as [number, number]),
    [waypoints],
  );

  const activeIndex =
    activeDay !== null
      ? waypoints.findIndex((w) => w.day === activeDay)
      : -1;

  const completedPositions =
    activeIndex > 0 ? routePositions.slice(0, activeIndex + 1) : [];

  if (waypoints.length === 0) return null;

  const center: [number, number] = [waypoints[0].lat, waypoints[0].lng];

  return (
    <div className="h-full w-full overflow-hidden rounded-2xl ring-1 ring-gray-200">
      <MapContainer
        center={center}
        zoom={10}
        scrollWheelZoom={false}
        zoomControl={false}
        dragging={false}
        doubleClickZoom={false}
        className="h-full w-full"
        style={{ minHeight: "400px" }}
      >
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        <MapController waypoints={waypoints} activeDay={activeDay} />

        {/* Full route (faded background) */}
        <Polyline
          positions={routePositions}
          pathOptions={{
            color: "#1b4332",
            weight: 3,
            opacity: 0.2,
            dashArray: "6 6",
          }}
        />

        {/* Completed route (highlighted) */}
        {completedPositions.length > 1 && (
          <Polyline
            positions={completedPositions}
            pathOptions={{
              color: "#e76f51",
              weight: 4,
              opacity: 0.9,
            }}
          />
        )}

        {/* Day markers */}
        {waypoints.map((wp, i) => {
          const isActive = activeDay === wp.day;
          const isCompleted = activeIndex >= 0 && i <= activeIndex;
          const label = lang === "zh" ? wp.labelZh : wp.labelEn;

          return (
            <CircleMarker
              key={`${wp.day}-${wp.lat}-${wp.lng}`}
              center={[wp.lat, wp.lng]}
              radius={isActive ? 9 : 5}
              pathOptions={{
                color: isActive
                  ? "#e76f51"
                  : isCompleted
                    ? "#e76f51"
                    : "#1b4332",
                fillColor: isActive
                  ? "#e76f51"
                  : isCompleted
                    ? "#e76f51"
                    : "#fff",
                fillOpacity: isActive ? 1 : isCompleted ? 0.8 : 0.5,
                weight: isActive ? 3 : 2,
              }}
            >
              <Tooltip
                direction="top"
                offset={[0, -8]}
                permanent={isActive}
                className="trek-tooltip"
              >
                <div className="text-center">
                  <div className="font-semibold">
                    {lang === "zh" ? `第${wp.day}天` : `Day ${wp.day}`}
                  </div>
                  <div className="text-xs opacity-80">{label}</div>
                  <div className="text-xs opacity-60">
                    {wp.altitude.toLocaleString()}m
                  </div>
                </div>
              </Tooltip>
            </CircleMarker>
          );
        })}
      </MapContainer>
    </div>
  );
}

