  --background: #faf9f6;
  --foreground: #1a1a1a;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-primary: #1b4332;
  --color-primary-light: #2d6a4f;
  --color-primary-dark: #081c15;
  --color-secondary: #d4a373;
  --color-secondary-light: #e9c89b;
  --color-accent: #e76f51;
  --color-accent-light: #f4a261;
  --color-muted: #6b7280;
  --color-muted-light: #f3f4f6;
  --font-sans: var(--font-inter), 'Noto Sans TC', system-ui, sans-serif;
}

body {
  background: var(--background);
  color: var(--foreground);
}

html {
  scroll-behavior: smooth;
}

/* Smooth fade-in animation */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideInFromLeft {
  from {
    opacity: 0;
    transform: translateX(-30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

main > section {
  animation: fadeIn 0.6s ease-out;
}

/* Custom scrollbar */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: var(--background);
}

::-webkit-scrollbar-thumb {
  background: #d4a373;
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: #c4935f;
}

/* Selection color */
::selection {
  background-color: #d4a37350;
  color: #081c15;
}

/* Focus styles */
*:focus-visible {
  outline: 2px solid #2d6a4f;
  outline-offset: 2px;
}

/* Line clamp utility */
.line-clamp-2 {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

