import Link from "next/link";
import Navigation from "./Navigation";
import LanguageSwitcher from "./LanguageSwitcher";
import type { Dictionary } from "@/app/[lang]/dictionaries";

export default function Header({
  lang,
  dict,
}: {
  lang: string;
  dict: Dictionary["nav"];
}) {
  const navItems = [
    { label: dict.home, href: "" },
    { label: dict.about, href: "/about" },
    { label: dict.treks, href: "/treks" },
    { label: dict.team, href: "/team" },
    { label: dict.gallery, href: "/gallery" },
    { label: dict.contact, href: "/contact" },
  ];

  return (
    <header className="sticky top-0 z-50 h-16 bg-primary-dark/95 backdrop-blur-sm">
      <div className="mx-auto flex h-full max-w-7xl items-center justify-between px-4 sm:px-6">
        <Link href={`/${lang}`} className="flex items-center gap-2">
          <span className="text-xl font-bold text-white">
            {lang === "zh" ? "發現尼泊爾" : "Find Nepal Trek"}
          </span>
        </Link>

        <div className="flex items-center gap-4">
          <Navigation items={navItems} lang={lang} />
          <LanguageSwitcher currentLang={lang} />
        </div>
      </div>
    </header>
  );
}

import Link from "next/link";
import type { Dictionary } from "@/app/[lang]/dictionaries";

export default function Footer({
  lang,
  dict,
}: {
  lang: string;
  dict: Dictionary["footer"];
}) {
  const navDict =
    lang === "zh"
      ? {
          about: "關於我們",
          treks: "行程",
          team: "我們團隊",
          gallery: "相簿",
          contact: "聯絡我們",
        }
      : {
          about: "About Us",
          treks: "Treks",
          team: "Our Team",
          gallery: "Photos",
          contact: "Contact",
        };

  return (
    <footer className="bg-primary-dark text-white">
      <div className="mx-auto max-w-7xl px-4 py-12 sm:px-6">
        <div className="grid gap-8 md:grid-cols-3">
          {/* Company info */}
          <div>
            <h3 className="mb-4 text-lg font-bold">
              {lang === "zh" ? "發現尼泊爾" : "Find Nepal Trek"}
            </h3>
            <p className="mb-2 text-sm text-white/70">{dict.company}</p>
            <p className="text-sm text-white/70">{dict.bilingual}</p>
          </div>

          {/* Quick links */}
          <div>
            <h3 className="mb-4 text-lg font-bold">{dict.quickLinks}</h3>
            <nav className="flex flex-col gap-2">
              {Object.entries(navDict).map(([key, label]) => (
                <Link
                  key={key}
                  href={`/${lang}/${key === "about" ? "about" : key}`}
                  className="text-sm text-white/70 transition-colors hover:text-white"
                >
                  {label}
                </Link>
              ))}
            </nav>
          </div>

          {/* Contact */}
          <div>
            <h3 className="mb-4 text-lg font-bold">{dict.contactUs}</h3>
            <div className="flex flex-col gap-2 text-sm text-white/70">
              <a
                href={`tel:${dict.phone}`}
                className="transition-colors hover:text-white"
              >
                {dict.phone}
              </a>
              <a
                href={`mailto:${dict.email}`}
                className="transition-colors hover:text-white"
              >
                {dict.email}
              </a>
              <p>{dict.address}</p>
            </div>
            <div className="mt-4 flex gap-4">
              <a
                href="https://www.facebook.com/"
                target="_blank"
                rel="noopener noreferrer"
                aria-label="Facebook"
                className="text-white/70 transition-colors hover:text-white"
              >
                <svg className="h-5 w-5" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z" />
                </svg>
              </a>
              <a
                href="https://www.instagram.com/find_nepal_trek"
                target="_blank"
                rel="noopener noreferrer"
                aria-label="Instagram"
                className="text-white/70 transition-colors hover:text-white"
              >
                <svg className="h-5 w-5" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M12 2.163c3.204 0 3.584.012 4.85.07 3.252.148 4.771 1.691 4.919 4.919.058 1.265.069 1.645.069 4.849 0 3.205-.012 3.584-.069 4.849-.149 3.225-1.664 4.771-4.919 4.919-1.266.058-1.644.07-4.85.07-3.204 0-3.584-.012-4.849-.07-3.26-.149-4.771-1.699-4.919-4.92-.058-1.265-.07-1.644-.07-4.849 0-3.204.013-3.583.07-4.849.149-3.227 1.664-4.771 4.919-4.919 1.266-.057 1.645-.069 4.849-.069zM12 0C8.741 0 8.333.014 7.053.072 2.695.272.273 2.69.073 7.052.014 8.333 0 8.741 0 12c0 3.259.014 3.668.072 4.948.2 4.358 2.618 6.78 6.98 6.98C8.333 23.986 8.741 24 12 24c3.259 0 3.668-.014 4.948-.072 4.354-.2 6.782-2.618 6.979-6.98.059-1.28.073-1.689.073-4.948 0-3.259-.014-3.667-.072-4.947-.196-4.354-2.617-6.78-6.979-6.98C15.668.014 15.259 0 12 0zm0 5.838a6.162 6.162 0 100 12.324 6.162 6.162 0 000-12.324zM12 16a4 4 0 110-8 4 4 0 010 8zm6.406-11.845a1.44 1.44 0 100 2.881 1.44 1.44 0 000-2.881z" />
                </svg>
              </a>
            </div>
          </div>
        </div>

        <div className="mt-8 border-t border-white/10 pt-8 text-center text-sm text-white/50">
          &copy; {dict.copyright}
        </div>
      </div>
    </footer>
  );
}

"use client";

import { useState } from "react";

interface FormDict {
  name: string;
  email: string;
  subject: string;
  message: string;
  submit: string;
  sending: string;
  success: string;
  error: string;
}

export default function ContactForm({ dict }: { dict: FormDict }) {
  const [status, setStatus] = useState<"idle" | "sending" | "sent" | "error">(
    "idle",
  );

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.currentTarget;
    const data = new FormData(form);
    const subject = data.get("subject") as string;
    const body = `Name: ${data.get("name")}\nEmail: ${data.get("email")}\n\n${data.get("message")}`;

    window.location.href = `mailto:info@findnepaltrek.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    setStatus("sent");
  };

  return (
    <div className="rounded-2xl bg-white p-8 shadow-lg ring-1 ring-gray-100">
      {status === "sent" ? (
        <div className="flex flex-col items-center justify-center py-12 text-center">
          <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-green-100">
            <svg className="h-8 w-8 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="m4.5 12.75 6 6 9-13.5" />
            </svg>
          </div>
          <p className="text-lg font-semibold text-primary-dark">
            {dict.success}
          </p>
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid gap-6 sm:grid-cols-2">
            <div>
              <label
                htmlFor="name"
                className="mb-2 block text-sm font-semibold text-primary-dark"
              >
                {dict.name}
              </label>
              <input
                type="text"
                id="name"
                name="name"
                required
                className="w-full rounded-xl border border-gray-200 px-4 py-3 text-foreground transition-colors focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
              />
            </div>
            <div>
              <label
                htmlFor="email"
                className="mb-2 block text-sm font-semibold text-primary-dark"
              >
                {dict.email}
              </label>
              <input
                type="email"
                id="email"
                name="email"
                required
                className="w-full rounded-xl border border-gray-200 px-4 py-3 text-foreground transition-colors focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
              />
            </div>
          </div>
          <div>
            <label
              htmlFor="subject"
              className="mb-2 block text-sm font-semibold text-primary-dark"
            >
              {dict.subject}
            </label>
            <input
              type="text"
              id="subject"
              name="subject"
              required
              className="w-full rounded-xl border border-gray-200 px-4 py-3 text-foreground transition-colors focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
            />
          </div>
          <div>
            <label
              htmlFor="message"
              className="mb-2 block text-sm font-semibold text-primary-dark"
            >
              {dict.message}
            </label>
            <textarea
              id="message"
              name="message"
              required
              rows={5}
              className="w-full rounded-xl border border-gray-200 px-4 py-3 text-foreground transition-colors focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
            />
          </div>
          <button
            type="submit"
            className="w-full rounded-full bg-accent py-3 font-semibold text-white transition-colors hover:bg-accent-light sm:w-auto sm:px-12"
          >
            {dict.submit}
          </button>
        </form>
      )}
    </div>
  );
}

