input.old_string:
"about": {
  "hero": {
    "title": "關於發現尼泊爾",
    "subtitle": "您在尼泊爾安全可靠的在地旅行社"
  },
  "story": {
    "title": "我們的故事",
    "content1": "發現尼泊爾誕生於兩種文化的結合與對山岳共同的熱愛。由專業資深的尼泊爾登山嚮導與他的台灣太太共同創立，我們搭建起東西方旅客與壯麗喜馬拉雅山脈之間的橋樑。",
    "content2": "我們的尼泊爾嚮導擁有數十年的登山專業經驗、國際認證，以及對尼泊爾每條步道、每個村莊和隱藏觀景點的深入了解。他的台灣太太則帶來細心的行程規劃能力，深刻理解華語旅客在異國需要什麼樣的照顧才能感到舒適安心。",
    "content3": "無論您是追求山中獨處的獨行旅人，還是一群朋友在尋找一生難忘的旅程，我們都會根據您的步調、偏好和夢想，量身客製每一趟旅程。我們不只是帶您看尼泊爾——我們幫您發現尼泊爾。"
  },
  "principles": {
    "title": "我們的核心理念",
    "subtitle": "引導我們一切行動的六大價值",
    "mountain": {
      "title": "高山探索",
      "description": "每次登山都是一趟自我成長與心靈探索的旅程。我們的專業嚮導帶領您穿越尼泊爾最令人嘆為觀止的地景，讓每一步都成為突破自我、改變人生的時刻。"
    },
    "culture": {
      "title": "文化融合",
      "description": "我們不僅僅是帶您走路線。我們的行程是沉浸式的體驗，將健行與深度文化理解交織在一起——與當地家庭共餐、參與村莊慶典、了解古老步道背後的故事。"
    },
    "safety": {
      "title": "安全至上",
      "description": "您的安全是不容妥協的。我們的國際認證嚮導團隊接受過高山醫學、高原反應預防和地形專業的訓練。我們攜帶完備的急救設備、衛星通訊裝置，並在每次探險中嚴格遵守安全準則。"
    },
    "environment": {
      "title": "環境永續",
      "description": "我們致力於減少生態足跡，積極支持我們所造訪的社區。我們實踐無痕山林原則，以公平的薪資聘僱當地挑夫，並為步道維護和村莊發展計畫做出貢獻。"
    },
    "accessible": {
      "title": "超越年齡的冒險",
      "description": "山是屬於每個人的。我們設計各種難度等級的路線，確保無論您的年齡或經驗如何，都有一趟完美的尼泊爾冒險在等著您。從輕鬆的山丘漫步到挑戰性的高海拔探險，我們讓旅程配合旅人。"
    },
    "digitalDetox": {
      "title": "數位斷捨離",
      "description": "在一個時刻保持連線的時代，我們提供難得的體驗：真正地放下手機。我們許多路線會經過沒有網路訊號的區域，給您一份全然活在當下的禮物——重新與大自然、同伴和自己連結。"
    }
  }
}

