input.old_string:
"about": {
  "hero": {
    "title": "About Find Nepal Trek",
    "subtitle": "Your safe and reliable local travel agency in Nepal"
  },
  "story": {
    "title": "Our Story",
    "content1": "Find Nepal Trek was born from the union of two cultures and a shared passion for the mountains. Founded by a professional and experienced Nepali trekking guide and his Taiwanese wife, we bridge the gap between Eastern and Western travelers and the magnificent Himalayas.",
    "content2": "Our Nepali guide brings decades of mountain expertise, international certifications, and an intimate knowledge of every trail, village, and hidden viewpoint in Nepal. His Taiwanese wife brings meticulous planning skills and a deep understanding of what Chinese-speaking travelers need to feel comfortable and cared for in a foreign land.",
    "content3": "Whether you're a solo adventurer seeking solitude in the mountains or a group of friends looking for the trip of a lifetime, we customize every journey to match your pace, preferences, and dreams. We don't just show you Nepal \u2014 we help you discover it."
  },
  "principles": {
    "title": "Our Core Principles",
    "subtitle": "Six values that guide everything we do",
    "mountain": {
      "title": "Mountain Exploration",
      "description": "Every trek is a journey of personal growth and spiritual discovery. Our professional guides lead you through Nepal's most awe-inspiring landscapes, turning each step into a breakthrough moment that challenges and transforms you."
    },
    "culture": {
      "title": "Cultural Integration",
      "description": "We go beyond simple route navigation. Our treks are immersive experiences that weave together hiking with deep cultural understanding \u2014 sharing meals with local families, participating in village ceremonies, and learning the stories behind ancient trails."
    },
    "safety": {
      "title": "Safety First",
      "description": "Your safety is non-negotiable. Our internationally certified guide team is trained in mountain medicine, altitude sickness prevention, and terrain expertise. We carry comprehensive first-aid kits, satellite communication devices, and maintain strict safety protocols on every expedition."
    },
    "environment": {
      "title": "Environmental Responsibility",
      "description": "We are committed to minimizing our ecological footprint and actively supporting the communities we visit. We practice Leave No Trace principles, hire local porters at fair wages, and contribute to trail maintenance and village development projects."
    },
    "accessible": {
      "title": "Accessible Adventures",
      "description": "The mountains are for everyone. We design routes for various difficulty levels, ensuring that regardless of your age or experience, there's a perfect Nepal adventure waiting for you. From gentle hill walks to challenging high-altitude expeditions, we match the journey to the traveler."
    },
    "digitalDetox": {
      "title": "Digital Detox",
      "description": "In an age of constant connectivity, we offer something rare: the chance to truly unplug. Many of our routes pass through areas with no network signal, giving you the gift of being fully present \u2014 reconnecting with nature, your companions, and yourself."
    }
  }
}

input.new_string:
"about": {
  "hero": {
    "title": "About Us",
    "subtitle": "Your safe and reliable local travel agency in Nepal"
  },
  "story": {
    "title": "About Us",
    "content1": "A professional and seasoned Nepali guide \u2014 a beloved son-in-law of Taiwan \u2014 leads you to discover the beauty of Nepal, while his Taiwanese wife helps you plan customized itineraries.",
    "content2": "Whether you're traveling solo or with a group of friends, we can arrange your perfect Nepal holiday.",
    "content3": "We are a safe and reliable local travel agency in Nepal. We don't just show you Nepal \u2014 we help you discover it."
  },
  "principles": {
    "title": "Our Core Principles",
    "subtitle": "Six values that guide everything we do",
    "mountain": {
      "title": "Mountain Exploration: A Journey Beyond Limits",
      "description": "Setting foot on the trail is more than a trip \u2014 it's a spiritual exploration and dialogue with yourself. Every step is a challenge, every view a reward. Our professional team will craft a bespoke adventure just for you, leading you across uncharted horizons to redefine your limits amid magnificent mountain landscapes. Stop imagining \u2014 let your dreams blossom with every step."
    },
    "culture": {
      "title": "Where Culture Meets Nature",
      "description": "Mountains are not just terrain \u2014 they are living history books. Our treks go beyond simple route navigation; they are immersive experiences that take you deep into local culture, indigenous life, and the pulse of nature. Every stretch of trail leads you into an entirely different world, measuring the boundary between civilization and wilderness with your own footsteps."
    },
    "safety": {
      "title": "Safe Journeys, Limitless Possibilities",
      "description": "On the road to your dreams, safety is never compromised. Our internationally trained guide team undergoes rigorous professional training \u2014 from high-altitude medicine to terrain expertise \u2014 safeguarding your every step. Whether you're a first-time adventurer or a seasoned mountaineer, we will create an unforgettable and safe journey for you."
    },
    "environment": {
      "title": "Sustainable Travel, Shared Future",
      "description": "We firmly believe that exploring nature should never come at the cost of the environment. On every trek, we are committed to minimizing our environmental impact and actively supporting local communities, making every step of your journey an act of respect and care for this land. Through responsible travel, we build a deeper connection with nature."
    },
    "accessible": {
      "title": "Adventures Beyond Age",
      "description": "Age is not a barrier to dreams \u2014 it is an accumulation of experience. We design routes of varying difficulty to ensure that every traveler passionate about nature can find their own challenge. From gentle mountain paths to heart-pounding high-altitude trails, we believe everyone has the right to explore the world."
    },
    "digitalDetox": {
      "title": "Offline Travel for the Digital Age",
      "description": "In a life surrounded by screens, we invite you to temporarily set aside your devices and reconnect with nature. Here, there are no network interruptions \u2014 only breathing, footsteps, scenery, and inner tranquility. Let us redefine the meaning of travel together, rediscovering authentic and pure life experiences in the mountains and forests."
    }
  }
}

