import { getDictionary, hasLocale } from "../dictionaries";
import { notFound } from "next/navigation";
import Image from "next/image";
import { team } from "@/data/team";
import { localized } from "@/lib/utils";
import type { Locale } from "@/lib/i18n";

export default async function TeamPage({
  params,
}: {
  params: Promise<{ lang: string }>;
}) {
  const { lang } = await params;
  if (!hasLocale(lang)) notFound();
  const dict = await getDictionary(lang);
  const l = lang as Locale;

  return (
    <>
      {/* Hero */}
      <section className="relative flex min-h-[40vh] items-center justify-center bg-primary-dark">
        <div className="absolute inset-0 bg-gradient-to-br from-primary-dark to-primary" />
        {/* Decorative mountain silhouette */}
        <div className="absolute bottom-0 left-0 right-0">
          <svg viewBox="0 0 1440 200" className="w-full text-background" fill="currentColor">
            <path d="M0,200 L0,120 Q180,40 360,100 Q540,160 720,80 Q900,0 1080,60 Q1260,120 1440,80 L1440,200 Z" />
          </svg>
        </div>
        <div className="relative z-10 mx-auto max-w-4xl px-4 text-center sm:px-6">
          <h1 className="mb-4 text-4xl font-bold text-white sm:text-5xl">
            {dict.team.title}
          </h1>
          <p className="text-lg text-white/80">{dict.team.subtitle}</p>
        </div>
      </section>

      {/* Team Grid */}
      <section className="py-20">
        <div className="mx-auto max-w-6xl px-4 sm:px-6">
          <div className="grid gap-10 md:grid-cols-2">
            {team.map((member) => (
              <div
                key={member.id}
                className="group overflow-hidden rounded-2xl bg-white shadow-md transition-all hover:shadow-xl"
              >
                <div className="flex flex-col sm:flex-row">
                  <div className="relative h-64 w-full overflow-hidden sm:h-auto sm:w-48 sm:shrink-0">
                    <div className="absolute inset-0 bg-gradient-to-br from-primary to-primary-light" />
                    {/* Placeholder avatar with initials */}
                    <div className="absolute inset-0 flex items-center justify-center">
                      <span className="text-5xl font-bold text-white/30">
                        {localized(member, "name", l).charAt(0)}
                      </span>
                    </div>
                  </div>
                  <div className="p-6">
                    <h3 className="mb-1 text-xl font-bold text-primary-dark">
                      {localized(member, "name", l)}
                    </h3>
                    <p className="mb-3 text-sm font-semibold text-accent">
                      {localized(member, "role", l)}
                    </p>
                    <p className="mb-4 text-sm leading-relaxed text-muted">
                      {localized(member, "bio", l)}
                    </p>
                    <div>
                      <span className="text-xs font-semibold uppercase tracking-wider text-muted">
                        {dict.team.languages}
                      </span>
                      <div className="mt-1 flex flex-wrap gap-1.5">
                        {member.languages.map((language) => (
                          <span
                            key={language}
                            className="rounded-full bg-primary/10 px-2.5 py-0.5 text-xs font-medium text-primary"
                          >
                            {language}
                          </span>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>
    </>
  );
}

