export type DifficultyLevel = "easy" | "moderate" | "challenging" | "strenuous";

export interface TrekItineraryDay {
  day: number;
  titleEn: string;
  titleZh: string;
  descriptionEn: string;
  descriptionZh: string;
  altitude?: number;
  walkingHours?: number;
}

export interface Trek {
  slug: string;
  nameEn: string;
  nameZh: string;
  descriptionEn: string;
  descriptionZh: string;
  difficulty: DifficultyLevel;
  durationDays: number;
  maxAltitude: number;
  priceUSD: number;
  bestSeasons: string[];
  bestSeasonsZh: string[];
  heroImage: string;
  images: string[];
  featured: boolean;
  itinerary: TrekItineraryDay[];
  includedEn: string[];
  includedZh: string[];
  highlightsEn: string[];
  highlightsZh: string[];
}

export interface TeamMember {
  id: string;
  nameEn: string;
  nameZh: string;
  roleEn: string;
  roleZh: string;
  bioEn: string;
  bioZh: string;
  image: string;
  languages: string[];
}

