"use client";

import { useState, useCallback } from "react";
import dynamic from "next/dynamic";
import type { TrekItineraryDay } from "@/types/trek";
import type { TrekWaypoint } from "@/data/trekCoordinates";
import type { Locale } from "@/lib/i18n";
import ItineraryAccordion from "./ItineraryAccordion";
import AltitudeProfile from "./AltitudeProfile";

// Dynamic import with ssr: false to avoid window is not defined
const TrekMap = dynamic(() => import("./TrekMap"), { ssr: false });

export default function ItineraryWithMap({
  itinerary,
  waypoints,
  lang,
  dayLabel,
  itineraryTitle,
}: {
  itinerary: TrekItineraryDay[];
  waypoints: TrekWaypoint[];
  lang: Locale;
  dayLabel: string;
  itineraryTitle: string;
}) {
  const [activeDay, setActiveDay] = useState<number | null>(
    itinerary[0]?.day ?? null,
  );

  const handleDayChange = useCallback((day: number) => {
    setActiveDay(day);
  }, []);

  return (
    <div className="grid gap-8 lg:grid-cols-5">
      {/* Itinerary - left side */}
      <div className="lg:col-span-3">
        <h2 className="mb-6 text-2xl font-bold text-primary-dark">
          {itineraryTitle}
        </h2>
        <ItineraryAccordion
          itinerary={itinerary}
          lang={lang}
          dayLabel={dayLabel}
          onDayChange={handleDayChange}
        />
      </div>

      {/* Map + altitude profile - sticky right side */}
      <div className="lg:col-span-2">
        <div className="sticky top-24 space-y-3">
          <div className="h-[400px] lg:h-[460px]">
            <TrekMap waypoints={waypoints} activeDay={activeDay} lang={lang} />
          </div>
          <AltitudeProfile
            waypoints={waypoints}
            activeDay={activeDay}
            lang={lang}
          />
        </div>
      </div>
    </div>
  );
}

