import { getDictionary, hasLocale } from "./dictionaries";
import { notFound } from "next/navigation";
import HeroBanner from "@/components/home/HeroBanner";
import ActivityCategories from "@/components/home/ActivityCategories";
import FeaturedTreks from "@/components/home/FeaturedTreks";
import Testimonials from "@/components/home/Testimonials";
import CTASection from "@/components/home/CTASection";

export default async function HomePage({
  params,
}: {
  params: Promise<{ lang: string }>;
}) {
  const { lang } = await params;
  if (!hasLocale(lang)) notFound();
  const dict = await getDictionary(lang);

  return (
    <>
      <HeroBanner lang={lang} dict={dict.home.hero} />
      <ActivityCategories dict={dict.home.activities} />
      <FeaturedTreks
        lang={lang}
        dict={dict.home.featuredTreks}
        treksDict={dict.treks}
      />
      <Testimonials dict={dict.home.testimonials} />
      <CTASection lang={lang} dict={dict.home.cta} />
    </>
  );
}

