import Link from "next/link";
import Image from "next/image";
import type { Dictionary } from "@/app/[lang]/dictionaries";

export default function HeroBanner({
  lang,
  dict,
}: {
  lang: string;
  dict: Dictionary["home"]["hero"];
}) {
  return (
    <section className="relative h-[90vh] min-h-[600px] overflow-hidden">
      {/* Full-bleed background image */}
      <Image
        src="/images/hero-bg.jpg"
        alt="Nepal Himalayan mountains"
        fill
        className="object-cover"
        priority
      />
      {/* Dark overlay — heavier at bottom for text legibility */}
      <div className="absolute inset-0 bg-gradient-to-b from-black/30 via-black/20 to-black/70" />

      {/* Content — pinned to bottom-left */}
      <div className="absolute inset-0 flex items-end">
        <div className="w-full px-6 pb-16 sm:px-10 lg:px-16 lg:pb-20">
          <div className="mx-auto max-w-7xl">
            {/* Bilingual badge — their real differentiator */}
            <div className="mb-5 inline-flex items-center gap-2 rounded-full bg-white/15 px-4 py-1.5 backdrop-blur-sm">
              <span className="text-sm font-medium text-white/90">
                {lang === "zh"
                  ? "中文英文都通 · 台灣女婿帶路"
                  : "Bilingual Guides · English & 中文"}
              </span>
            </div>

            <h1 className="mb-4 max-w-2xl text-4xl font-bold leading-[1.1] text-white sm:text-5xl lg:text-6xl">
              {lang === "zh" ? (
                <>探索尼泊爾的壯闊山徑</>
              ) : (
                <>
                  Discover Nepal&apos;s
                  <br />
                  Hidden Trails
                </>
              )}
            </h1>

            <p className="mb-8 max-w-lg text-base leading-relaxed text-white/80 sm:text-lg">
              {dict.subtitle}
            </p>

            <div className="flex flex-wrap gap-3">
              <Link
                href={`/${lang}/treks`}
                className="inline-flex items-center gap-2 rounded-lg bg-accent px-7 py-3.5 text-base font-semibold text-white transition-colors hover:bg-accent-light"
              >
                {dict.cta}
                <svg
                  className="h-4 w-4"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                  strokeWidth={2.5}
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    d="M13.5 4.5 21 12m0 0-7.5 7.5M21 12H3"
                  />
                </svg>
              </Link>
              <Link
                href={`/${lang}/about`}
                className="inline-flex items-center rounded-lg border border-white/40 px-7 py-3.5 text-base font-semibold text-white transition-colors hover:bg-white/10"
              >
                {dict.secondary}
              </Link>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

