import Link from "next/link";
import Image from "next/image";
import type { Dictionary } from "@/app/[lang]/dictionaries";

export default function HeroBanner({
  lang,
  dict,
}: {
  lang: string;
  dict: Dictionary["home"]["hero"];
}) {
  return (
    <section className="relative h-[60vh] min-h-[450px] overflow-hidden">
      {/* Full-bleed background image */}
      <Image
        src="/images/hero-bg.jpg"
        alt="Nepal Himalayan mountains"
        fill
        className="object-cover"
        priority
      />
      {/* Dark overlay — heavier at bottom for text legibility */}
      <div className="absolute inset-0 bg-gradient-to-b from-black/30 via-black/20 to-black/70" />

      {/* Content — pinned to bottom-left */}
      <div className="absolute inset-0 flex items-end">
        <div className="w-full px-6 pb-16 sm:px-10 lg:px-16 lg:pb-20">
          <div className="mx-auto max-w-7xl">
            {/* Bilingual badge — their real differentiator */}
            <div className="mb-5 inline-flex items-center gap-2 rounded-full bg-white/15 px-4 py-1.5 backdrop-blur-sm">
              <span className="text-sm font-medium text-white/90">
                {lang === "zh"
                  ? "中文英文都通 · 台灣女婿帶路"
                  : "Bilingual Guides · English & 中文"}
              </span>
            </div>

            <h1 className="mb-4 max-w-2xl text-4xl font-bold leading-[1.1] text-white sm:text-5xl lg:text-6xl">
              {lang === "zh" ? (
                <>探索尼泊爾的壯闊山徑</>
              ) : (
                <>
                  Discover Nepal&apos;s
                  <br />
                  Hidden Trails
                </>
              )}
            </h1>

            <p className="mb-8 max-w-lg text-base leading-relaxed text-white/80 sm:text-lg">
              {dict.subtitle}
            </p>

            <div className="flex flex-wrap gap-3">
              <Link
                href={`/${lang}/treks`}
                className="inline-flex items-center gap-2 rounded-lg bg-accent px-7 py-3.5 text-base font-semibold text-white transition-colors hover:bg-accent-light"
              >
                {dict.cta}
                <svg
                  className="h-4 w-4"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                  strokeWidth={2.5}
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    d="M13.5 4.5 21 12m0 0-7.5 7.5M21 12H3"
                  />
                </svg>
              </Link>
              <Link
                href={`/${lang}/about`}
                className="inline-flex items-center rounded-lg border border-white/40 px-7 py-3.5 text-base font-semibold text-white transition-colors hover:bg-white/10"
              >
                {dict.secondary}
              </Link>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

import Link from "next/link";
import Image from "next/image";
import type { Dictionary } from "@/app/[lang]/dictionaries";
import { treks } from "@/data/treks";
import { localized } from "@/lib/utils";
import type { Locale } from "@/lib/i18n";

export default function FeaturedTreks({
  lang,
  dict,
  treksDict,
}: {
  lang: string;
  dict: Dictionary["home"]["featuredTreks"];
  treksDict: Dictionary["treks"];
}) {
  const featured = treks.filter((t) => t.featured);

  return (
    <section className="bg-background py-24">
      <div className="mx-auto max-w-7xl px-4 sm:px-6">
        <div className="mb-16 flex flex-col items-center justify-between gap-4 sm:flex-row">
          <div>
            <span className="mb-2 inline-block text-sm font-semibold uppercase tracking-widest text-accent">
              {dict.title}
            </span>
            <p className="max-w-md text-muted">{dict.subtitle}</p>
          </div>
          <Link
            href={`/${lang}/treks`}
            className="group inline-flex items-center gap-2 rounded-full border-2 border-primary px-6 py-3 font-semibold text-primary transition-all hover:bg-primary hover:text-white"
          >
            {dict.viewAll}
            <svg
              className="h-4 w-4 transition-transform group-hover:translate-x-1"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
              strokeWidth={2}
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M13.5 4.5 21 12m0 0-7.5 7.5M21 12H3"
              />
            </svg>
          </Link>
        </div>

        <div className="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
          {featured.map((trek, i) => (
            <Link
              key={trek.slug}
              href={`/${lang}/treks/${trek.slug}`}
              className={`group relative overflow-hidden rounded-3xl bg-white shadow-md transition-all hover:-translate-y-2 hover:shadow-2xl ${
                i === 0 ? "md:col-span-2 lg:col-span-1" : ""
              }`}
            >
              <div className="relative h-72 overflow-hidden">
                <Image
                  src={trek.heroImage}
                  alt={localized(trek, "name", lang as Locale)}
                  fill
                  className="object-cover transition-transform duration-700 group-hover:scale-105"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent" />

