import { getDictionary, hasLocale } from "../dictionaries";
import { notFound } from "next/navigation";
import GalleryGrid from "@/components/gallery/GalleryGrid";

const galleryImages = [
  { src: "/images/gallery/1.jpg", alt: "Himalayan mountain vista" },
  { src: "/images/gallery/2.jpg", alt: "Prayer flags at Everest Base Camp" },
  { src: "/images/gallery/3.jpg", alt: "Trekkers crossing suspension bridge" },
  { src: "/images/gallery/4.jpg", alt: "Annapurna sunrise from Poon Hill" },
  { src: "/images/gallery/5.jpg", alt: "Traditional Sherpa village" },
  { src: "/images/gallery/6.jpg", alt: "Rhododendron forest in spring" },
  { src: "/images/gallery/7.jpg", alt: "Yak caravan on mountain trail" },
  { src: "/images/gallery/8.jpg", alt: "Tengboche Monastery" },
  { src: "/images/gallery/9.jpg", alt: "Langtang Valley panorama" },
  { src: "/images/gallery/10.jpg", alt: "Sunset over Kathmandu" },
  { src: "/images/gallery/11.jpg", alt: "Upper Mustang red cliffs" },
  { src: "/images/gallery/12.jpg", alt: "Mountain lake reflection" },
];

export default async function GalleryPage({
  params,
}: {
  params: Promise<{ lang: string }>;
}) {
  const { lang } = await params;
  if (!hasLocale(lang)) notFound();
  const dict = await getDictionary(lang);

  return (
    <>
      {/* Hero */}
      <section className="relative flex min-h-[40vh] items-center justify-center bg-primary-dark">
        <div className="absolute inset-0 bg-gradient-to-br from-primary-dark via-primary to-primary-light opacity-90" />
        <div className="relative z-10 mx-auto max-w-4xl px-4 text-center sm:px-6">
          <h1 className="mb-4 text-4xl font-bold text-white sm:text-5xl">
            {dict.gallery.title}
          </h1>
          <p className="text-lg text-white/80">{dict.gallery.subtitle}</p>
        </div>
      </section>

      {/* Gallery */}
      <section className="py-16">
        <div className="mx-auto max-w-7xl px-4 sm:px-6">
          <GalleryGrid images={galleryImages} />
        </div>
      </section>
    </>
  );
}

