import { getDictionary, hasLocale } from "../dictionaries";
import { notFound } from "next/navigation";
import GalleryGrid from "@/components/gallery/GalleryGrid";

const galleryImages = [
  { src: "/images/gallery/1.jpg", alt: "Himalayan mountain vista" },
  { src: "/images/gallery/2.jpg", alt: "Prayer flags at Everest Base Camp" },
  { src: "/images/gallery/3.jpg", alt: "Trekkers crossing suspension bridge" },
  { src: "/images/gallery/4.jpg", alt: "Annapurna sunrise from Poon Hill" },
  { src: "/images/gallery/5.jpg", alt: "Traditional Sherpa village" },
  { src: "/images/gallery/6.jpg", alt: "Rhododendron forest in spring" },
  { src: "/images/gallery/7.jpg", alt: "Yak caravan on mountain trail" },
  { src: "/images/gallery/8.jpg", alt: "Tengboche Monastery" },
  { src: "/images/gallery/9.jpg", alt: "Langtang Valley panorama" },
  { src: "/images/gallery/10.jpg", alt: "Sunset over Kathmandu" },
  { src: "/images/gallery/11.jpg", alt: "Upper Mustang red cliffs" },
  { src: "/images/gallery/12.jpg", alt: "Mountain lake reflection" },
];

export default async function GalleryPage({
  params,
}: {
  params: Promise<{ lang: string }>;
}) {
  const { lang } = await params;
  if (!hasLocale(lang)) notFound();
  const dict = await getDictionary(lang);

  return (
    <>
      {/* Hero */}
      <section className="relative flex min-h-[40vh] items-center justify-center bg-primary-dark">
        <div className="absolute inset-0 bg-gradient-to-br from-primary-dark via-primary to-primary-light opacity-90" />
        <div className="relative z-10 mx-auto max-w-4xl px-4 text-center sm:px-6">
          <h1 className="mb-4 text-4xl font-bold text-white sm:text-5xl">
            {dict.gallery.title}
          </h1>
          <p className="text-lg text-white/80">{dict.gallery.subtitle}</p>
        </div>
      </section>

      {/* Gallery */}
      <section className="py-16">
        <div className="mx-auto max-w-7xl px-4 sm:px-6">
          <GalleryGrid images={galleryImages} />
        </div>
      </section>
    </>
  );
}

import { getDictionary, hasLocale } from "../dictionaries";
import { notFound } from "next/navigation";

const principleKeys = [
  "mountain",
  "culture",
  "safety",
  "environment",
  "accessible",
  "digitalDetox",
] as const;

const principleAccents = [
  "border-emerald-600 text-emerald-600",
  "border-amber-600 text-amber-600",
  "border-blue-600 text-blue-600",
  "border-green-600 text-green-600",
  "border-purple-600 text-purple-600",
  "border-cyan-600 text-cyan-600",
];

export default async function AboutPage({
  params,
}: {
  params: Promise<{ lang: string }>;
}) {
  const { lang } = await params;
  if (!hasLocale(lang)) notFound();
  const dict = await getDictionary(lang);

  return (
    <>
      {/* Hero */}
      <section className="relative flex min-h-[50vh] items-center justify-center overflow-hidden bg-primary-dark">
        <div
          className="absolute inset-0 bg-cover bg-center bg-no-repeat opacity-30"
          style={{ backgroundImage: "url(/images/about-hero.jpg)" }}
        />
        <div className="absolute inset-0 bg-gradient-to-b from-primary-dark/50 to-primary-dark/90" />
        <div className="relative z-10 mx-auto max-w-4xl px-4 text-center sm:px-6">
          <h1 className="mb-4 text-4xl font-bold text-white sm:text-5xl">
            {dict.about.hero.title}
          </h1>
          <p className="text-xl text-white/80">{dict.about.hero.subtitle}</p>
        </div>
      </section>

      {/* Our Story */}
      <section className="py-20">
        <div className="mx-auto max-w-4xl px-4 sm:px-6">
          <h2 className="mb-8 text-center text-3xl font-bold text-primary-dark sm:text-4xl">
            {dict.about.story.title}
          </h2>
          <div className="relative">
            {/* Decorative line */}
            <div className="absolute left-0 top-0 h-full w-1 rounded-full bg-gradient-to-b from-secondary via-accent to-primary" />
            <div className="space-y-6 pl-8">
              <p className="text-lg leading-relaxed text-foreground/80">
                {dict.about.story.content1}
              </p>
              <p className="text-lg leading-relaxed text-foreground/80">
                {dict.about.story.content2}
              </p>
              <p className="text-lg leading-relaxed text-foreground/80">
                {dict.about.story.content3}
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* Core Principles */}
      <section className="bg-muted-light py-20">
        <div className="mx-auto max-w-7xl px-4 sm:px-6">
          <div className="mb-12 text-center">
            <h2 className="mb-4 text-3xl font-bold text-primary-dark sm:text-4xl">
              {dict.about.principles.title}
            </h2>
            <p className="text-muted">{dict.about.principles.subtitle}</p>
          </div>

          <div className="grid gap-6 md:grid-cols-2">
            {principleKeys.map((key, i) => {
              const principle = dict.about.principles[key];
              const num = String(i + 1).padStart(2, "0");
              return (
                <div
                  key={key}
                  className={`relative rounded-lg border-l-4 ${principleAccents[i].split(" ")[0]} bg-white py-6 pr-8 pl-8 shadow-sm ring-1 ring-gray-100 transition-all hover:shadow-lg`}
                >
                  <span
                    className={`absolute top-4 right-6 text-6xl font-black leading-none opacity-[0.07]`}
                  >
                    {num}
                  </span>
                  <h3 className="mb-2 text-lg font-bold text-primary-dark">
                    {principle.title}
                  </h3>
                  <p className="text-sm leading-relaxed text-muted">
                    {principle.description}
                  </p>
                </div>
              );
            })}
          </div>
        </div>
      </section>

      {/* Stats Section — commented out until real numbers are confirmed
      <section className="bg-primary py-16">
        <div className="mx-auto grid max-w-5xl grid-cols-2 gap-8 px-4 sm:px-6 md:grid-cols-4">
          {[
            { value: "15+", labelEn: "Years Experience", labelZh: "年經驗" },
            { value: "500+", labelEn: "Happy Trekkers", labelZh: "位快樂旅客" },
            { value: "20+", labelEn: "Trek Routes", labelZh: "條路線" },
            { value: "100%", labelEn: "Safety Record", labelZh: "安全紀錄" },
          ].map((stat) => (
            <div key={stat.value} className="text-center">
              <div className="text-4xl font-bold text-white sm:text-5xl">
                {stat.value}
              </div>
              <div className="mt-2 text-sm text-white/70">
                {lang === "zh" ? stat.labelZh : stat.labelEn}
              </div>
            </div>
          ))}
        </div>
      </section>
      */}
    </>
  );
}

import { getDictionary, hasLocale } from "../dictionaries";
import { notFound } from "next/navigation";
import Link from "next/link";
import Image from "next/image";
import { treks } from "@/data/treks";
import { localized } from "@/lib/utils";
import type { Locale } from "@/lib/i18n";

export default async function TreksPage({
  params,
}: {
  params: Promise<{ lang: string }>;
}) {
  const { lang } = await params;
  if (!hasLocale(lang)) notFound();
  const dict = await getDictionary(lang);

  return (
    <>
      {/* Hero */}
      <section className="relative flex min-h-[40vh] items-center justify-center bg-primary-dark">
        <div
          className="absolute inset-0 bg-cover bg-center bg-no-repeat opacity-20"
          style={{ backgroundImage: "url(/images/banner.jpg)" }}
        />
        <div className="absolute inset-0 bg-gradient-to-b from-primary-dark/60 to-primary-dark/90" />
        <div className="relative z-10 mx-auto max-w-4xl px-4 text-center sm:px-6">
          <h1 className="mb-4 text-4xl font-bold text-white sm:text-5xl">
            {dict.treks.title}
          </h1>
          <p className="text-lg text-white/80">{dict.treks.subtitle}</p>
        </div>
      </section>

      {/* Trek listing */}
      <section className="py-16">
        <div className="mx-auto max-w-7xl px-4 sm:px-6">
          <div className="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
            {treks.map((trek) => (
              <Link
                key={trek.slug}
                href={`/${lang}/treks/${trek.slug}`}
                className="group overflow-hidden rounded-2xl bg-white shadow-md transition-all hover:-translate-y-2 hover:shadow-xl"
              >
                <div className="relative h-60 overflow-hidden">
                  <Image
                    src={trek.heroImage}
                    alt={localized(trek, "name", lang as Locale)}
                    fill
                    className="object-cover transition-transform duration-700 group-hover:scale-110"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent" />

                  {/* Difficulty badge */}
                  <span
                    className={`absolute right-4 top-4 rounded-full px-3 py-1 text-xs font-bold text-white shadow-lg ${
                      trek.difficulty === "easy"
                        ? "bg-green-500"
                        : trek.difficulty === "moderate"
                          ? "bg-yellow-500"
                          : trek.difficulty === "challenging"
                            ? "bg-orange-500"
                            : "bg-red-500"
                    }`}
                  >
                    {dict.treks.difficultyLevels[trek.difficulty]}
                  </span>

                  {/* Price overlay */}
                  <div className="absolute bottom-4 left-4">
                    <span className="text-2xl font-bold text-white">
                      ${trek.priceUSD}
                    </span>
                    <span className="ml-1 text-sm text-white/80">
                      /{dict.treks.perPerson}
                    </span>
                  </div>
                </div>

                <div className="p-6">
                  <h3 className="mb-3 text-xl font-bold text-primary-dark group-hover:text-primary-light">
                    {localized(trek, "name", lang as Locale)}
                  </h3>
                  <p className="mb-4 line-clamp-2 text-sm text-muted">
                    {localized(trek, "description", lang as Locale)}
                  </p>

                  <div className="flex items-center gap-4 text-sm text-muted">
                    <div className="flex items-center gap-1">
                      <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 0 1 2.25-2.25h13.5A2.25 2.25 0 0 1 21 7.5v11.25m-18 0A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75m-18 0v-7.5A2.25 2.25 0 0 1 5.25 9h13.5A2.25 2.25 0 0 1 21 11.25v7.5" />
                      </svg>
                      <span>
                        {trek.durationDays} {dict.treks.days}
                      </span>
                    </div>
                    <div className="flex items-center gap-1">
                      <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M3 7.5 7.5 3m0 0L12 7.5M7.5 3v13.5m13.5-6L16.5 15m0 0L12 10.5m4.5 4.5V1.5" />
                      </svg>
                      <span>{trek.maxAltitude.toLocaleString()}m</span>
                    </div>
                  </div>

                  <div className="mt-4 flex items-center font-semibold text-accent">
                    {dict.treks.viewDetails}
                    <svg className="ml-1 h-4 w-4 transition-transform group-hover:translate-x-1" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M13.5 4.5 21 12m0 0-7.5 7.5M21 12H3" />
                    </svg>
                  </div>
                </div>
              </Link>
            ))}
          </div>
        </div>
      </section>
    </>
  );
}

