      <section className="bg-primary py-16">
        <div className="mx-auto grid max-w-5xl grid-cols-2 gap-8 px-4 sm:px-6 md:grid-cols-4">
          {[
            { value: "15+", labelEn: "Years Experience", labelZh: "年經驗" },
            { value: "500+", labelEn: "Happy Trekkers", labelZh: "位快樂旅客" },
            { value: "20+", labelEn: "Trek Routes", labelZh: "條路線" },
            { value: "100%", labelEn: "Safety Record", labelZh: "安全紀錄" },
