import Link from "next/link";
import Image from "next/image";
import type { Dictionary } from "@/app/[lang]/dictionaries";
import { treks } from "@/data/treks";
import { localized } from "@/lib/utils";
import type { Locale } from "@/lib/i18n";

export default function FeaturedTreks({
  lang,
  dict,
  treksDict,
}: {
  lang: string;
  dict: Dictionary["home"]["featuredTreks"];
  treksDict: Dictionary["treks"];
}) {
  const featured = treks.filter((t) => t.featured);

  return (
    <section className="bg-background py-24">
      <div className="mx-auto max-w-7xl px-4 sm:px-6">
        <div className="mb-16 flex flex-col items-center justify-between gap-4 sm:flex-row">
          <div>
            <span className="mb-2 inline-block text-sm font-semibold uppercase tracking-widest text-accent">
              {dict.title}
            </span>
            <p className="max-w-md text-muted">{dict.subtitle}</p>
          </div>
          <Link
            href={`/${lang}/treks`}
            className="group inline-flex items-center gap-2 rounded-full border-2 border-primary px-6 py-3 font-semibold text-primary transition-all hover:bg-primary hover:text-white"
          >
            {dict.viewAll}
            <svg
              className="h-4 w-4 transition-transform group-hover:translate-x-1"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
              strokeWidth={2}
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M13.5 4.5 21 12m0 0-7.5 7.5M21 12H3"
              />
            </svg>
          </Link>
        </div>

        <div className="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
          {featured.map((trek, i) => (
            <Link
              key={trek.slug}
              href={`/${lang}/treks/${trek.slug}`}
              className={`group relative overflow-hidden rounded-3xl bg-white shadow-md transition-all hover:-translate-y-2 hover:shadow-2xl ${
                i === 0 ? "md:col-span-2 lg:col-span-1" : ""
              }`}
            >
              <div className="relative h-72 overflow-hidden">
                <Image
                  src={trek.heroImage}
                  alt={localized(trek, "name", lang as Locale)}
                  fill
                  className="object-cover transition-transform duration-700 group-hover:scale-105"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent" />

                {/* Difficulty + Duration pills on image */}
                <div className="absolute left-4 top-4 flex gap-2">
                  <span
                    className={`rounded-full px-3 py-1 text-xs font-bold text-white backdrop-blur-sm ${
                      trek.difficulty === "easy"
                        ? "bg-green-500/80"
                        : trek.difficulty === "moderate"
                          ? "bg-yellow-500/80"
                          : trek.difficulty === "challenging"
                            ? "bg-orange-500/80"
                            : "bg-red-500/80"
                    }`}
                  >
                    {treksDict.difficultyLevels[trek.difficulty]}
                  </span>
                </div>

                {/* Price badge */}
                <div className="absolute bottom-4 right-4 rounded-xl bg-white/10 px-4 py-2 backdrop-blur-md">
                  <span className="text-sm text-white/70">{treksDict.price} </span>
                  <span className="text-xl font-bold text-white">
                    ${trek.priceUSD}
                  </span>
                </div>
              </div>

              <div className="p-6">
                <h3 className="mb-2 text-xl font-bold text-primary-dark transition-colors group-hover:text-primary-light">
                  {localized(trek, "name", lang as Locale)}
                </h3>
                <p className="mb-5 line-clamp-2 text-sm leading-relaxed text-muted">
                  {localized(trek, "description", lang as Locale)}
                </p>

                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-4 text-sm text-muted">
                    <span className="flex items-center gap-1.5">
                      <svg className="h-4 w-4 text-secondary" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 0 1 2.25-2.25h13.5A2.25 2.25 0 0 1 21 7.5v11.25m-18 0A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75m-18 0v-7.5A2.25 2.25 0 0 1 5.25 9h13.5A2.25 2.25 0 0 1 21 11.25v7.5" />
                      </svg>
                      {trek.durationDays} {treksDict.days}
                    </span>
                    <span className="flex items-center gap-1.5">
                      <svg className="h-4 w-4 text-secondary" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={1.5}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M3 7.5 7.5 3m0 0L12 7.5M7.5 3v13.5m13.5-6L16.5 15m0 0L12 10.5m4.5 4.5V1.5" />
                      </svg>
                      {trek.maxAltitude.toLocaleString()}m
                    </span>
                  </div>

                  <span className="inline-flex items-center gap-1 font-semibold text-accent transition-all group-hover:gap-2">
                    {treksDict.viewDetails}
                    <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M13.5 4.5 21 12m0 0-7.5 7.5M21 12H3" />
                    </svg>
                  </span>
                </div>
              </div>
            </Link>
          ))}
        </div>
      </div>
    </section>
  );
}

import type { Dictionary } from "@/app/[lang]/dictionaries";

export default function Testimonials({
  dict,
}: {
  dict: Dictionary["home"]["testimonials"];
}) {
  return (
    <section className="relative overflow-hidden bg-primary-dark py-24">
      {/* Background decoration */}
      <div className="absolute inset-0 opacity-5">
        <svg className="h-full w-full" viewBox="0 0 100 100" fill="currentColor" preserveAspectRatio="none">
          <path d="M0,100 L0,60 Q10,40 20,55 Q30,70 40,45 Q50,20 60,35 Q70,50 80,30 Q90,10 100,25 L100,100 Z" className="text-white" />
        </svg>
      </div>

      <div className="relative mx-auto max-w-7xl px-4 sm:px-6">
        <div className="mb-16 text-center">
          <span className="mb-3 inline-block text-sm font-semibold uppercase tracking-widest text-secondary">
            {dict.title}
          </span>
          <p className="mx-auto max-w-2xl text-white/60">{dict.subtitle}</p>
        </div>

        <div className="grid gap-8 md:grid-cols-3">
          {dict.items.map((item, i) => (
            <div
              key={i}
              className="group relative rounded-3xl bg-white/5 p-8 backdrop-blur-sm ring-1 ring-white/10 transition-all hover:bg-white/10 hover:ring-white/20"
            >
              {/* Large quote mark */}
              <div className="mb-4 text-5xl font-serif leading-none text-secondary/40">
                &ldquo;
              </div>
              <p className="mb-8 leading-relaxed text-white/80">{item.text}</p>
