"use client";

import { useState } from "react";
import Link from "next/link";

interface NavItem {
  label: string;
  href: string;
}

export default function Navigation({
  items,
  lang,
}: {
  items: NavItem[];
  lang: string;
}) {
  const [open, setOpen] = useState(false);

  return (
    <>
      <button
        className="text-white md:hidden"
        onClick={() => setOpen(!open)}
        aria-label="Toggle menu"
      >
        <svg
          className="h-6 w-6"
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          {open ? (
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M6 18L18 6M6 6l12 12"
            />
          ) : (
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M4 6h16M4 12h16M4 18h16"
            />
          )}
        </svg>
      </button>

      {/* Desktop nav */}
      <nav className="hidden items-center gap-6 md:flex">
        {items.map((item) => (
          <Link
            key={item.href}
            href={`/${lang}${item.href}`}
            className="text-sm font-medium text-white/80 transition-colors hover:text-white"
          >
            {item.label}
          </Link>
        ))}
      </nav>

      {/* Mobile nav */}
      {open && (
        <div className="absolute left-0 top-full w-full bg-primary-dark/95 backdrop-blur-sm md:hidden">
          <nav className="flex flex-col px-6 py-4">
            {items.map((item) => (
              <Link
                key={item.href}
                href={`/${lang}${item.href}`}
                className="border-b border-white/10 py-3 text-sm font-medium text-white/80 transition-colors hover:text-white"
                onClick={() => setOpen(false)}
              >
                {item.label}
              </Link>
            ))}
          </nav>
        </div>
      )}
    </>
  );
}

import Link from "next/link";
import type { Dictionary } from "@/app/[lang]/dictionaries";

export default function Footer({
  lang,
  dict,
}: {
  lang: string;
  dict: Dictionary["footer"];
}) {
  const navDict =
    lang === "zh"
      ? {
          about: "關於我們",
          treks: "行程",
          team: "我們團隊",
          gallery: "相簿",
        }
      : {
          about: "About Us",
          treks: "Treks",
          team: "Our Team",
          gallery: "Photos",
        };

  return (
    <footer className="bg-primary-dark text-white">
      <div className="mx-auto max-w-7xl px-4 py-12 sm:px-6">
        <div className="grid gap-8 md:grid-cols-3">
          {/* Company info */}
          <div>
            <h3 className="mb-4 text-lg font-bold">
              {lang === "zh" ? "發現尼泊爾" : "Find Nepal Trek"}
            </h3>
            <p className="mb-2 text-sm text-white/70">{dict.company}</p>
            <p className="text-sm text-white/70">{dict.bilingual}</p>
          </div>

          {/* Quick links */}
          <div>
            <h3 className="mb-4 text-lg font-bold">{dict.quickLinks}</h3>
            <nav className="flex flex-col gap-2">
              {Object.entries(navDict).map(([key, label]) => (
                <Link
                  key={key}
                  href={`/${lang}/${key === "about" ? "about" : key}`}
                  className="text-sm text-white/70 transition-colors hover:text-white"
                >
                  {label}
                </Link>
