                {dict.phone}
              </a>
              <a
                href={`mailto:${dict.email}`}
                className="transition-colors hover:text-white"
              >
                {dict.email}
              </a>
              <p>{dict.address}</p>
            </div>
            <div className="mt-4 flex gap-4">
              <a
