"use client";

import { useState, useEffect } from "react";
import Link from "next/link";

export default function StickyTrekHeader({
  trekName,
  difficulty,
  difficultyLabel,
  durationDays,
  maxAltitude,
  priceUSD,
  lang,
  daysLabel,
  perPersonLabel,
  bookLabel,
}: {
  trekName: string;
  difficulty: string;
  difficultyLabel: string;
  durationDays: number;
  maxAltitude: number;
  priceUSD: number;
  lang: string;
  daysLabel: string;
  perPersonLabel: string;
  bookLabel: string;
}) {
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const onScroll = () => {
      // Show after scrolling past the hero (60vh ≈ window height * 0.6)
      setVisible(window.scrollY > window.innerHeight * 0.5);
    };

    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const difficultyColor =
    difficulty === "easy"
      ? "bg-green-500"
      : difficulty === "moderate"
        ? "bg-yellow-500"
        : difficulty === "challenging"
          ? "bg-orange-500"
          : "bg-red-500";

  return (
    <div
      className={`fixed left-0 right-0 top-16 z-40 transition-all duration-300 ${
        visible
          ? "translate-y-0 opacity-100"
          : "-translate-y-full opacity-0 pointer-events-none"
      }`}
    >
      <div className="border-b border-white/10 bg-primary-dark/90 backdrop-blur-md shadow-lg">
        <div className="mx-auto flex max-w-7xl items-center justify-between gap-4 px-4 py-2.5 sm:px-6">
          {/* Left: name + stats */}
          <div className="flex min-w-0 items-center gap-3">
            <h2 className="truncate text-sm font-bold text-white sm:text-base">
              {trekName}
            </h2>
            <div className="hidden items-center gap-2 sm:flex">
              <span className={`h-2 w-2 rounded-full ${difficultyColor}`} />
              <span className="text-xs text-white/60">{difficultyLabel}</span>
              <span className="text-white/20">|</span>
              <span className="text-xs text-white/60">
                {durationDays} {daysLabel}
              </span>
              <span className="text-white/20">|</span>
              <span className="text-xs text-white/60">
                {maxAltitude.toLocaleString()}m
              </span>
            </div>
          </div>

          {/* Right: price + CTA */}
          <div className="flex shrink-0 items-center gap-3">
            <div className="hidden text-right sm:block">
              <span className="text-lg font-bold text-white">
                ${priceUSD}
              </span>
              <span className="ml-1 text-xs text-white/50">
                /{perPersonLabel}
              </span>
            </div>
            <Link
              href={`/${lang}/contact`}
              className="rounded-full bg-accent px-5 py-1.5 text-sm font-semibold text-white transition-colors hover:bg-accent-light"
            >
              {bookLabel}
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}

