import { getDictionary, hasLocale } from "../../dictionaries";
import { notFound } from "next/navigation";
import Link from "next/link";
import Image from "next/image";
import { treks } from "@/data/treks";
import { localized } from "@/lib/utils";
import type { Locale } from "@/lib/i18n";
import { trekCoordinates } from "@/data/trekCoordinates";
import ItineraryWithMap from "@/components/treks/ItineraryWithMap";
import StickyTrekHeader from "@/components/treks/StickyTrekHeader";

export async function generateStaticParams() {
  return treks.map((trek) => ({ slug: trek.slug }));
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ lang: string; slug: string }>;
}) {
  const { lang, slug } = await params;
  const trek = treks.find((t) => t.slug === slug);
  if (!trek || !hasLocale(lang)) return {};
  return {
    title: `${localized(trek, "name", lang as Locale)} | Find Nepal Trek`,
    description: localized(trek, "description", lang as Locale).slice(0, 160),
  };
}

export default async function TrekDetailPage({
  params,
}: {
  params: Promise<{ lang: string; slug: string }>;
}) {
  const { lang, slug } = await params;
  if (!hasLocale(lang)) notFound();
  const trek = treks.find((t) => t.slug === slug);
  if (!trek) notFound();
  const dict = await getDictionary(lang);
  const l = lang as Locale;
  const waypoints = trekCoordinates[trek.slug] ?? [];

  const difficultyColor =
    trek.difficulty === "easy"
      ? "bg-green-100 text-green-800"
      : trek.difficulty === "moderate"
        ? "bg-yellow-100 text-yellow-800"
        : trek.difficulty === "challenging"
          ? "bg-orange-100 text-orange-800"
          : "bg-red-100 text-red-800";

  return (
    <>
      <StickyTrekHeader
        trekName={localized(trek, "name", l)}
        difficulty={trek.difficulty}
        difficultyLabel={dict.treks.difficultyLevels[trek.difficulty]}
        durationDays={trek.durationDays}
        maxAltitude={trek.maxAltitude}
        priceUSD={trek.priceUSD}
        lang={lang}
        daysLabel={dict.treks.days}
        perPersonLabel={dict.treks.perPerson}
        bookLabel={dict.treks.bookNow}
      />

      {/* Hero */}
      <section className="relative flex min-h-[60vh] items-end overflow-hidden bg-primary-dark">
        <Image
          src={trek.heroImage}
          alt={localized(trek, "name", l)}
          fill
          className="object-cover"
          priority
        />
        <div className="absolute inset-0 bg-gradient-to-t from-primary-dark via-primary-dark/40 to-transparent" />
        <div className="relative z-10 mx-auto w-full max-w-7xl px-4 pb-12 sm:px-6">
          <Link
            href={`/${lang}/treks`}
            className="mb-4 inline-flex items-center gap-1 text-sm text-white/70 transition-colors hover:text-white"
          >
            <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M10.5 19.5 3 12m0 0 7.5-7.5M3 12h18" />
            </svg>
            {dict.treks.backToTreks}
          </Link>
          <h1 className="mb-4 text-4xl font-bold text-white sm:text-5xl">
            {localized(trek, "name", l)}
          </h1>
          <div className="flex flex-wrap items-center gap-3">
            <span className={`rounded-full px-4 py-1.5 text-sm font-bold ${difficultyColor}`}>
              {dict.treks.difficultyLevels[trek.difficulty]}
            </span>
            <span className="rounded-full bg-white/20 px-4 py-1.5 text-sm font-medium text-white backdrop-blur-sm">
              {trek.durationDays} {dict.treks.days}
            </span>
            <span className="rounded-full bg-white/20 px-4 py-1.5 text-sm font-medium text-white backdrop-blur-sm">
              {trek.maxAltitude.toLocaleString()}m
            </span>
          </div>
        </div>
      </section>

      {/* Info bar */}
      <section className="border-b border-gray-100 bg-white">
        <div className="mx-auto flex max-w-7xl flex-wrap items-center justify-between gap-4 px-4 py-4 sm:px-6">
          <div className="flex flex-wrap items-center gap-6 text-sm">
            <div>
              <span className="text-muted">{dict.treks.duration}: </span>
              <span className="font-semibold">{trek.durationDays} {dict.treks.days}</span>
            </div>
            <div>
              <span className="text-muted">{dict.treks.maxAltitude}: </span>
              <span className="font-semibold">{trek.maxAltitude.toLocaleString()}m</span>
            </div>
            <div>
              <span className="text-muted">{dict.treks.bestSeason}: </span>
              <span className="font-semibold">
                {(l === "zh" ? trek.bestSeasonsZh : trek.bestSeasons).join(", ")}
              </span>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-2xl font-bold text-primary-dark">${trek.priceUSD}</span>
            <span className="text-sm text-muted">/{dict.treks.perPerson}</span>
            <Link
              href={`/${lang}/contact`}
              className="rounded-full bg-accent px-6 py-2 text-sm font-semibold text-white transition-colors hover:bg-accent-light"
            >
              {dict.treks.bookNow}
            </Link>
          </div>
        </div>
      </section>

      <section className="py-16">
        <div className="mx-auto max-w-7xl px-4 sm:px-6">
          {/* Description */}
          <div className="mb-16 max-w-3xl">
            {localized(trek, "description", l)
              .split("\n\n")
              .map((p, i) => (
                <p key={i} className="mb-4 text-lg leading-relaxed text-foreground/80">
                  {p}
                </p>
              ))}
          </div>

          {/* Highlights */}
          <div className="mb-16">
            <h2 className="mb-6 text-2xl font-bold text-primary-dark">
              {dict.treks.highlights}
            </h2>
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {(l === "zh" ? trek.highlightsZh : trek.highlightsEn).map(
                (h, i) => (
                  <div key={i} className="flex items-start gap-3 rounded-lg bg-muted-light p-4">
                    <svg className="mt-0.5 h-5 w-5 shrink-0 text-accent" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.857-9.809a.75.75 0 00-1.214-.882l-3.483 4.79-1.88-1.88a.75.75 0 10-1.06 1.061l2.5 2.5a.75.75 0 001.137-.089l4-5.5z" clipRule="evenodd" />
                    </svg>
                    <span className="text-foreground/80">{h}</span>
                  </div>
                ),
              )}
            </div>
          </div>

          {/* Itinerary + Map side by side */}
          <div className="mb-16">
            <ItineraryWithMap
              itinerary={trek.itinerary}
              waypoints={waypoints}
              lang={l}
              dayLabel={dict.treks.dayLabel}
              itineraryTitle={dict.treks.itinerary}
            />
          </div>

          {/* What's included */}
          <div className="max-w-3xl">
            <h2 className="mb-6 text-2xl font-bold text-primary-dark">
              {dict.treks.included}
            </h2>
            <div className="grid gap-3 sm:grid-cols-2">
              {(l === "zh" ? trek.includedZh : trek.includedEn).map(
                (item, i) => (
                  <div key={i} className="flex items-center gap-3">
                    <svg className="h-5 w-5 shrink-0 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth={2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="m4.5 12.75 6 6 9-13.5" />
                    </svg>
                    <span className="text-foreground/80">{item}</span>
                  </div>
                ),
              )}
            </div>
          </div>

          {/* Bottom CTA */}
          <div className="mt-16 rounded-2xl bg-primary-dark p-8 text-center sm:p-12">
            <h3 className="mb-3 text-2xl font-bold text-white">
              {dict.treks.bookNow}
            </h3>
            <p className="mb-6 text-white/70">
              {localized(trek, "name", l)} · ${trek.priceUSD} /{dict.treks.perPerson}
            </p>
            <div className="flex flex-col items-center gap-3 sm:flex-row sm:justify-center">
              <Link
                href={`/${lang}/contact`}
                className="rounded-full bg-accent px-8 py-3 font-semibold text-white transition-colors hover:bg-accent-light"
              >
                {dict.treks.bookNow}
              </Link>
              <Link
                href={`/${lang}/contact`}
                className="rounded-full border-2 border-white/30 px-8 py-3 font-semibold text-white transition-colors hover:bg-white/10"
              >
                {dict.treks.inquire}
              </Link>
            </div>
          </div>
        </div>
      </section>
    </>
  );
}

